//! 🧪️ Neutral event rows quote the actual command box, field copies and string capacities.
use super::*;
use semio_framework_plugin::HostEvent;
#[test]
fn host_event_birth_profile_matches_actual_command_and_neutral_bytes(){
 let fixture:semio_framework_value::serde_json::Value=semio_framework_value::serde_json::from_str(include_str!("fixture.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let window_id=fixture["windowId"].as_str().unwrap().to_owned();let event=match row["kind"].as_str().unwrap(){"blur"=>HostEvent::WindowBlurred{window_id},"captureLost"=>HostEvent::PointerCaptureLost{window_id},"utilityChanged"=>HostEvent::UtilityChanged{window_id,from:Some("ignored-from".into()),to:Some("ignored-to".into())},"frozen"=>HostEvent::TimeTravelFrozen{window_id},"baseMoved"=>HostEvent::BaseMoved{window_id},"retiring"=>HostEvent::Retiring{window_id},_=>unreachable!()};let demand=<LayoutPlayApp as ArtifactEditor>::host_event_demands(&event);let command=<LayoutPlayApp as ArtifactEditor>::host_event(&event);if row["bodyBytes"].is_null(){assert!(demand.is_none()&&command.is_none());continue}let command=command.unwrap();let demand=demand.unwrap();let LayoutCommand::TranslateSelection(value)=command else{panic!("exact host command")};assert!(value.ids.is_empty());let strings=[value.phase.as_ref().unwrap(),value.reason.as_ref().unwrap()];let bytes=strings.iter().map(|value|value.len()).sum::<usize>();let capacity=strings.iter().map(|value|value.capacity()).sum::<usize>();assert_eq!(bytes,row["bodyBytes"].as_u64().unwrap()as usize);assert_eq!(capacity,bytes);let header=std::mem::size_of::<LayoutCommand>();assert_eq!(demand.copy_bytes,header*fixture["headerCopies"].as_u64().unwrap()as usize+bytes);assert_eq!(demand.capacity_bytes,header*fixture["boxedHeaders"].as_u64().unwrap()as usize+capacity);assert_eq!(demand.depth,fixture["depth"].as_u64().unwrap()as usize);assert_eq!(demand.release_bytes,0);}
}
